{"url": "https://api.openalex.org/works?search=formal+criteria+for+evaluating+novelty+and+significance+of+scientific+research+questions+in+autonomous+systems&per-page=4&select=id%2Cdoi%2Ctitle%2Cpublication_year%2Ctype%2Ccited_by_count%2Copen_access%2Cprimary_location%2Cabstract_inverted_index", "scope": "OpenAlex scholarly metadata and reconstructed abstracts where supplied; not full papers", "excerpt": "[{"id": "https://openalex.org/W7160824208", "doi": "https://doi.org/10.5281/zenodo.20127842", "title": "ZeroPaper: An Autonomous Research System", "publication_year": 2026, "type": "report", "cited_by_count": 1, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://instituteforautomatedresearch.org/papers/iar-m/iar-m-001.pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:doi:10.5281/zenodo.20127842", "doi": null, "is_oa": true, "landing_page_url": "https://instituteforautomatedresearch.org/papers/iar-m/iar-m-001", "pdf_url": "https://instituteforautomatedresearch.org/papers/iar-m/iar-m-001.pdf", "source": null, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "Working paper"}, "abstract": "ZeroPaper is an autonomous system that takes a research domain as input and produces a publication-candidate manuscript as output, with no human intervention between launch and completion. The system runs ten numbered stages and six adversarial gates, coordinates roughly thirty specialized agents, and produces finished LaTeX for economics at roughly two dollars per paper amortized under a flat-fee Claude Code Max subscription (approximately zero marginal cost per additional paper). From ten premises about how LLMs behave and what they cost, we derive six design principles for long-running autonomous systems: keep state and control flow outside the model, spend context carefully, delegate aggressively, verify rather than trust, make termination mechanical, and run independent work in parallel. ZeroPaper runs on Claude Code, OpenAI Codex, and Gemini CLI, with variants for finance and macro and extensions for empirical analysis and LLM experiments."}, {"id": "https://openalex.org/W7150754777", "doi": "https://doi.org/10.62311/nesx/rp3-30042026", "title": "Explainable Quantum-Logical Multi-Agent Systems for Autonomous Scientific Discovery in High-Dimensional Research Landscapes", "publication_year": 2026, "type": "article", "cited_by_count": 0, "open_access": {"is_oa": true, "oa_status": "bronze", "oa_url": "https://www.nationaleducationservices.org/file-download/1620346/Download Full-Text Research Paper PDF-A3.pdf", "any_repository_has_fulltext": false}, "primary_location": {"id": "doi:10.62311/nesx/rp3-30042026", "doi": "https://doi.org/10.62311/nesx/rp3-30042026", "is_oa": true, "landing_page_ur

